import java.util.Scanner;

public class Main {
    static int total_n, total_k, modulus;
    static long[] fact = new long[250004];
    static long[] inv_fact = new long[250004];
    static long[][] memo_dp = new long[27][250004];

    static int get_lowbit_value(int x) {
        return x & (-x);
    }

    static long power_mod(long base, int exponent) {
        long result = 1;
        while (exponent > 0) {
            if ((exponent & 1) == 1) {
                result = (result * base) % modulus;
            }
            base = (base * base) % modulus;
            exponent >>= 1;
        }
        return result;
    }

    static void precompute() {
        fact[0] = 1;
        for (int i = 1; i <= total_n; i++) {
            fact[i] = (fact[i - 1] * i) % modulus;
        }
        inv_fact[total_n] = power_mod(fact[total_n], modulus - 2);
        for (int i = total_n - 1; i >= 0; i--) {
            inv_fact[i] = (inv_fact[i + 1] * (i + 1)) % modulus;
        }
    }

    static long recurse(int x, int s) {
        if (memo_dp[x][s] != -1) {
            return memo_dp[x][s];
        }
        if (s == 0) {
            return memo_dp[x][s] = ((fact[total_n] * fact[total_k]) % modulus) * inv_fact[total_k - x] % modulus;
        }
        int remaining = s - get_lowbit_value(s);
        long sum_result = 0;
        for (int t = remaining; t != 0; t = (t - 1) & remaining) {
            sum_result = (sum_result + recurse(x + 1, t) * inv_fact[s - t]) % modulus;
        }
        sum_result = (sum_result + recurse(x + 1, 0) * inv_fact[s]) % modulus;
        return memo_dp[x][s] = sum_result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        total_n = sc.nextInt();
        total_k = sc.nextInt();
        modulus = sc.nextInt();
        precompute();
        long answer = power_mod(total_k, total_n);
        if (total_n % 2 == 0) {
            for (int i = 0; i <= 26; i++) {
                for (int j = 0; j <= total_n; j++) {
                    memo_dp[i][j] = -1;
                }
            }
            answer = (answer - recurse(0, total_n) + modulus) % modulus;
        }
        System.out.println(answer);
        sc.close();
    }
}
